package com.smart.agent.tool.progress;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.web.reactive.function.client.WebClient;@Configuration(proxyBeanMethods=false)public class ProjectProgressBusinessClientConfiguration{@Bean @ConditionalOnProperty(prefix="agent.business",name="mode",havingValue="smart-boot",matchIfMissing=true) ProjectProgressBusinessClient client(ObjectMapper m,@Value("${agent.business.base-url:http://localhost:8888}")String u,@Value("${AGENT_LOCAL_CONTEXT_SECRET:}")String s){return new SmartBootProjectProgressBusinessClient(WebClient.builder().baseUrl(u).build(),m,s);}}
